head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.autoComplete1_onchange = function(info) {
	var newValue = info.newValue;

	if(newValue == "001"){
		console.log("Hanoi");
		autoComplete1.setNextTabID("input1");
		var nextTabID = autoComplete1.getNextTabID();
		console.log("nextTab ::  "+nextTabID  );
	} else if(newValue == "002"){
		console.log("Danang");
		autoComplete1.setNextTabID("mf_input2");
		var nextTabID = autoComplete1.getNextTabID();
		console.log("nextTab ::  "+nextTabID  );
	}
};

scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
	scwin.simulateWrapper('#autoComplete1', 'key-combo', {
		combo: 'TAB'
	});
}
scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#mf_input1').hasClass('w2input_focus');
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1').click()");
	WebSquare.wUnit.addCommand("pause", "400");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_itemTable_1').click()");
	WebSquare.wUnit.addCommand("pause", "400");		

	WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
	WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
